    ctx.fillStyle = col; ctx.beginPath(); ctx.moveTo(ex + hx * 2, ey + hy * 2); ctx.lineTo(ex - hx * hl - hy * hw, ey - hy * hl + hx * hw); ctx.lineTo(ex - hx * hl + hy * hw, ey - hy * hl - hx * hw); ctx.closePath(); ctx.fill();
