function draw(ctx, state, t, ui) {
  var b = state.beta, c = ui.c, name = ["sure", "ok", "hmm", "lol"], ref = [0.55, 0.3, 0.12, 0.03], rew = [0.2, 0.5, 0.4, 2], p = [], q = [], i;
